func Verify(cfg Config, wire []byte) (network.Command, protocol.Envelope, error) {
	var step protocol.Envelope
	if err := protocol.DecodeStrict(wire, &step, 16<<10); err != nil {
		return network.Command{}, step, err
	}
	if err := protocol.VerifyEnvelope(step, protocol.EnvelopeScope{Region: cfg.Cell, Kind: "netbird.step", Actor: cfg.Node,
		OperationID: step.OperationID, Epoch: step.Epoch, Generation: step.Generation}, cfg.Controller, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: StepLifetime, ClockSkew: time.Second}); err != nil {
		return network.Command{}, step, err
	}
	var command network.Command
	if err := json.Unmarshal(step.Payload, &command, json.RejectUnknownMembers(true)); err != nil {
		return command, step, err
	}
	if command.ID != step.OperationID || !entityid.Valid(command.Transaction) || command.ID != network.CommandID(command.Transaction, command.Action) || step.Epoch == 0 || command.Generation == 0 || command.Generation != step.Generation {
		return command, step, errors.New("invalid NetBird command binding")
	}
	if command.Action != "install" && command.Action != "confirm" && command.Action != "rollback" {
		return command, step, errors.New("invalid NetBird action")
	}
	if err := client.ValidatePin(command.Target.Pin); err != nil {
		return command, step, err
	}
	if err := command.Target.Enrollment.Validate(); err != nil {
		return command, step, err
	}
	return command, step, nil
}

// Relay stages only bytes named in the verified cell pin. It never executes
// an archive or interprets a controller-supplied filesystem path.
func Relay(ctx context.Context, cfg Config, wire []byte, fetch func(context.Context, string, io.Writer) error) error {
	command, _, err := Verify(cfg, wire)
	if err != nil {
		return err
	}
	spool, err := openSpool(cfg.Directory, true)
	if err != nil {
		return err
	}
	defer spool.close()
	if command.Action == "install" {
		pin, err := command.Target.Pin.Archive(runtime.GOARCH)
		if err != nil {
			return err
		}
		destination := "binary-" + pin.BinarySHA256
		if client.VerifyBinary(spool.path(destination), pin.BinarySHA256, runtime.GOARCH) != nil {
			file, temporary, err := spool.temporary()
			if err != nil {
				return err
			}
			defer spool.remove(temporary)
			err = fetch(ctx, pin.BinarySHA256, file)
			if err == nil {
				err = file.Sync()
			}
			err = errors.Join(err, file.Close())
			if err != nil {
				return err
			}
			if err := client.VerifyBinary(spool.path(temporary), pin.BinarySHA256, runtime.GOARCH); err != nil {
				return err
			}
			if err := spool.rename(temporary, destination); err != nil {
				return err
			}
		} else if err := spool.sync(destination, client.MaxBinaryBytes); err != nil {
			// Cached bytes may predate durability checks or an interrupted rename sync.
			return err
		}
	}
	// The transfer can exceed the signed step's short lifetime. The next
	// exchange supplies a fresh signature; it reuses the verified artifact.
	if _, _, err := Verify(cfg, wire); err != nil {
		return err
	}
	return spool.write("step.json", wire)
}

func (p Pin) Archive(architecture string) (Archive, error) {
	switch architecture {
	case "arm64":
		return p.Archives.Arm64, nil
	case "amd64":
		return p.Archives.AMD64, nil
	}
	return Archive{}, errors.New("unsupported architecture")
}
func SHA256(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}
func ValidatePin(p Pin) error {
	if !regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`).MatchString(p.Version) {
		return errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	for _, arch := range []string{"arm64", "amd64"} {
		a, _ := p.Archive(arch)
		expected := fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", p.Version, p.Version, arch)
		if a.URL != expected {
			return fmt.Errorf("invalid NetBird %s archive source", arch)
		}
		if a.Bytes <= 0 || a.Bytes > MaxBinaryBytes {
			return fmt.Errorf("invalid NetBird %s archive size", arch)
		}
		if !SHA256Pattern.MatchString(a.SHA256) || !SHA256Pattern.MatchString(a.BinarySHA256) {
			return fmt.Errorf("invalid NetBird %s SHA-256", arch)
		}
	}
	return nil
}

func VerifyBinary(path, expected, architecture string) error {
	return verifyBinaryLimit(path, expected, architecture, MaxBinaryBytes)
}

func verifyBinaryLimit(path, expected, architecture string, maximum int64) error {
	if !SHA256Pattern.MatchString(expected) {
		return errors.New("NetBird binary SHA-256 must be 64 lowercase hex characters")
	}
	f, e := openBoundedFileLimit(path, 64, maximum)
	if e != nil {
		return e
	}
	defer f.Close()
	var header [64]byte
	if _, e = io.ReadFull(f, header[:]); e != nil {
		return e
	}
	machine := uint16(183)
	if architecture == "amd64" {
		machine = 62
	} else if architecture != "arm64" {
		return errors.New("unsupported architecture")
	}
	if string(header[:7]) != "\x7fELF\x02\x01\x01" || (binary.LittleEndian.Uint16(header[16:]) != 2 && binary.LittleEndian.Uint16(header[16:]) != 3) || binary.LittleEndian.Uint16(header[18:]) != machine || binary.LittleEndian.Uint32(header[20:]) != 1 || binary.LittleEndian.Uint16(header[52:]) != 64 {
		return fmt.Errorf("NetBird binary must be an ELF64 little-endian %s executable", architecture)
	}
	h := sha256.New()
	h.Write(header[:])
	n, e := io.Copy(h, io.LimitReader(f, maximum+1-int64(len(header))))
	if e != nil {
		return e
	}
	if n+int64(len(header)) > maximum {
		return fmt.Errorf("NetBird binary exceeds %d bytes", maximum)
	}
	if hex.EncodeToString(h.Sum(nil)) != expected {
		return errors.New("NetBird binary bytes differ from the pinned SHA-256")
	}
	return nil
}

func openBoundedFile(path string, minimum int64) (*os.File, error) {
	return openBoundedFileLimit(path, minimum, MaxBinaryBytes)
}

func openBoundedFileLimit(path string, minimum, maximum int64) (*os.File, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() < minimum || info.Size() > maximum {
		file.Close()
		return nil, fmt.Errorf("NetBird source must be a direct regular file within %d bytes", maximum)
	}
	return file, nil
}

