func (m managedClient) installBootstrapConfig(ctx context.Context, configRoot string, pin Pin, cfg netbird.Config) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	lock, err := m.lock()
	if err != nil {
		return false, err
	}
	defer lock.Close()
	transaction, err := m.readTransaction()
	if err != nil || transaction.TransactionID != "" {
		return false, err
	}
	if err := ValidateManagedVersion(pin.Version); err != nil {
		return false, err
	}
	if err := ValidatePin(pin); err != nil {
		return false, err
	}
	if err := cfg.Validate(); err != nil {
		return false, err
	}
	relative, err := filepath.Rel(m.root, configRoot)
	if err != nil || !filepath.IsAbs(configRoot) || relative == ".." || strings.HasPrefix(relative, "../") {
		return false, errors.New("NetBird bootstrap configuration must be within the managed root")
	}
	if _, err := secureManagedDirectory(m.root, "/"+relative, 0755); err != nil {
		return false, err
	}
	// Keep readers and fresh snapshots held until both mirrors are durable.
	marker := filepath.Join(configRoot, bootstrapPendingFile)
	if err := atomicManagedFile(marker, []byte("publication incomplete\n"), 0600); err != nil {
		return false, err
	}
	for _, file := range []struct {
		name  string
		value any
	}{{"netbird-pin.json", pin}, {"netbird.json", cfg}} {
		if err := ctx.Err(); err != nil {
			return false, err
		}
		body, err := json.Marshal(file.value)
		if err != nil {
			return false, err
		}
		if err := atomicManagedFile(filepath.Join(configRoot, file.name), body, 0644); err != nil {
			return false, err
		}
	}
	if err := ctx.Err(); err != nil {
		return false, err
	}
	if err := removeManagedFile(marker); err != nil {
		return false, err
	}
	return true, nil
}

func secureManagedDirectory(root, path string, mode os.FileMode) (string, error) {
	directory, err := directDirectory(root, path, mode, false)
	if err != nil {
		return "", err
	}
	current := root
	for _, part := range strings.Split(strings.TrimPrefix(path, "/"), "/") {
		current = filepath.Join(current, part)
		info, err := os.Lstat(current)
		if err != nil {
			return "", err
		}
		stat, ok := info.Sys().(*syscall.Stat_t)
		if !ok || stat.Uid != uint32(os.Geteuid()) || info.Mode().Perm()&0022 != 0 {
			return "", errors.New("managed NetBird parents must be owned by root without group or other write access")
		}
	}
	if mode == 0700 {
		return directory, os.Chmod(directory, mode)
	}
	return directory, nil
}

func (m managedClient) lock() (*os.File, error) {
	directory, err := secureManagedDirectory(m.root, managedDirectory, 0700)
	if err != nil {
		return nil, err
	}
	fd, err := syscall.Open(filepath.Join(directory, "managed.lock"), syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0600)
	if err != nil {
		return nil, errors.New("cannot open managed NetBird lock")
	}
	lock := os.NewFile(uintptr(fd), "managed.lock")
	info, err := lock.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0600 {
		lock.Close()
		return nil, errors.New("managed NetBird lock must be a private regular file")
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || stat.Uid != uint32(os.Geteuid()) {
		lock.Close()
		return nil, errors.New("managed NetBird lock has an unexpected owner")
	}
	if syscall.Flock(fd, syscall.LOCK_EX|syscall.LOCK_NB) != nil {
		lock.Close()
		return nil, errors.New("another managed NetBird operation is running")
	}
	return lock, nil
}

func atomicManagedFile(path string, body []byte, mode os.FileMode) error {
	if info, err := os.Lstat(path); err == nil && !info.Mode().IsRegular() {
		return errors.New("managed NetBird destination must be a direct regular file")
	} else if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	f, err := os.CreateTemp(filepath.Dir(path), ".netbird-managed-")
	if err != nil {
		return err
	}
	defer os.Remove(f.Name())
	defer f.Close()
	if err = f.Chmod(mode); err != nil {
		return err
	}
	if _, err = f.Write(body); err != nil {
		return err
	}
	if err = errors.Join(f.Sync(), f.Close()); err != nil {
		return err
	}
	if err = os.Rename(f.Name(), path); err != nil {
		return err
	}
	return syncManagedDirectory(filepath.Dir(path))
}

func syncManagedDirectory(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func removeManagedFile(path string) error {
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	// Retry must sync absence too; an interrupted install may lack its parent.
	for parent := filepath.Dir(path); ; parent = filepath.Dir(parent) {
		err := syncManagedDirectory(parent)
		if !errors.Is(err, os.ErrNotExist) || filepath.Dir(parent) == parent {
			return err
		}
	}
}

func (m managedClient) readTransaction() (managedTransaction, error) {
	path := m.path(managedDirectory + "/pending.json")
	body, info, err := readManagedStateFileLimit(path, 4096)
	if err != nil || info.Exists && info.Mode != 0600 {
		return managedTransaction{}, errors.New("managed NetBird transaction must be a bounded private file")
	}
	if !info.Exists {
		return managedTransaction{}, nil
	}
	var transaction managedTransaction
	if json.Unmarshal(body, &transaction, json.RejectUnknownMembers(true)) != nil ||
		!entityid.Valid(transaction.TransactionID) || !SHA256Pattern.MatchString(transaction.BinarySHA256) ||
		transaction.PreviousSHA256 != "" && !SHA256Pattern.MatchString(transaction.PreviousSHA256) ||
		transaction.RollbackSHA256 != "" && !SHA256Pattern.MatchString(transaction.RollbackSHA256) ||
		transaction.Architecture != "arm64" && transaction.Architecture != "amd64" || transaction.RollbackDeadline.IsZero() {
		return managedTransaction{}, errors.New("managed NetBird transaction is invalid")
	}
	return transaction, nil
}

func (m managedClient) writeTransaction(transaction managedTransaction) error {
	body, err := json.Marshal(transaction)
	if err != nil {
		return err
	}
	return atomicManagedFile(m.path(managedDirectory+"/pending.json"), body, 0600)
}

func ValidatePin(p Pin) error {
	if !regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`).MatchString(p.Version) {
		return errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	for _, arch := range []string{"arm64", "amd64"} {
		a, _ := p.Archive(arch)
		expected := fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", p.Version, p.Version, arch)
		if a.URL != expected {
			return fmt.Errorf("invalid NetBird %s archive source", arch)
		}
		if a.Bytes <= 0 || a.Bytes > MaxBinaryBytes {
			return fmt.Errorf("invalid NetBird %s archive size", arch)
		}
		if !SHA256Pattern.MatchString(a.SHA256) || !SHA256Pattern.MatchString(a.BinarySHA256) {
			return fmt.Errorf("invalid NetBird %s SHA-256", arch)
		}
	}
	return nil
}

func directDirectory(root, path string, mode os.FileMode, enforce bool) (string, error) {
	destination := root
	parts := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for i, part := range parts {
		destination = filepath.Join(destination, part)
		s, e := os.Lstat(destination)
		if e == nil && !s.IsDir() {
			return "", fmt.Errorf("installation parent must be a direct directory: %s", destination)
		}
		if e != nil && !os.IsNotExist(e) {
			return "", e
		}
		if os.IsNotExist(e) {
			m := os.FileMode(0755)
			if i == len(parts)-1 {
				m = mode
			}
			if e = os.Mkdir(destination, m); e != nil {
				return "", e
			}
		}
	}
	if enforce {
		if e := os.Chmod(destination, mode); e != nil {
			return "", e
		}
	}
	return destination, nil
}

func LoadConfig(path string) (Config, error) {
	return loadConfig(path, false)
}

// LoadControllerConfig reads the public configuration from an unprivileged
// controller. The file must still be a regular file owned by root or the
// caller without group or other write access. A missing file reports
// os.ErrNotExist so callers can leave NetBird management off.
func LoadControllerConfig(path string) (Config, error) {
	if _, err := os.Lstat(path); errors.Is(err, os.ErrNotExist) {
		return Config{}, os.ErrNotExist
	}
	return loadConfig(path, true)
}

// Validate checks public enrollment settings without reading OCI Vault.
func (cfg Config) Validate() error {
	_, err := cfg.normalized()
	return err
}

func loadConfig(path string, rootOwned bool) (Config, error) {
	if path == "" || !strings.HasPrefix(path, "/") {
		return Config{}, errors.New("netbird-enroll requires an absolute --config path")
	}
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return Config{}, errors.New("cannot open NetBird enrollment configuration")
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !(ownedRegular(info, 0o022) || rootOwned && rootOwnedRegular(info, 0o022)) || info.Size() > maxConfigBytes {
		owner := "root"
		if rootOwned {
			owner = "root or the caller"
		}
		return Config{}, fmt.Errorf("NetBird configuration must be a regular file owned by %s, without group or other write access, and at most %d bytes", owner, maxConfigBytes)
	}
	wire, err := io.ReadAll(io.LimitReader(file, maxConfigBytes+1))
	if err != nil || len(wire) > maxConfigBytes {
		return Config{}, errors.New("cannot read bounded NetBird enrollment configuration")
	}
	var cfg Config
	if err := json.Unmarshal(wire, &cfg, json.RejectUnknownMembers(true)); err != nil {
		return Config{}, errors.New("invalid NetBird enrollment configuration JSON")
	}
	return cfg.normalized()
}

func (cfg Config) normalized() (Config, error) {
	if cfg.ManagementURL == "" {
		cfg.ManagementURL = DefaultManagementURL
	}
	if cfg.Region == "" {
		cfg.Region = DefaultRegion
	}
	manager, err := normalizeManagerURL(cfg.ManagementURL)
	if err != nil {
		return Config{}, err
	}
	cfg.ManagementURL = manager
	if cfg.ManagementIP != "" {
		ip, err := netip.ParseAddr(cfg.ManagementIP)
		if err != nil || !ip.IsPrivate() || ip.Zone() != "" || ip.Is4In6() {
			return Config{}, errors.New("NetBird management_ip must be a private IPv4 or IPv6 address")
		}
		cfg.ManagementIP = ip.String()
	}
	if !ValidSecretID(cfg.Region, cfg.SetupKeySecretID) {
		return Config{}, errors.New("NetBird setup_key_secret_id must identify an OCI Vault secret in the configured region")
	}
	if cfg.AdminPATSecretID != "" && !ValidSecretID(cfg.Region, cfg.AdminPATSecretID) {
		return Config{}, errors.New("NetBird admin_pat_secret_id must identify an OCI Vault secret in the configured region")
	}
	if err := ValidatePeerNames(cfg.PeerNames); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

func ValidateManagedVersion(version string) error {
	if !managedVersionPattern.MatchString(version) {
		return errors.New("managed NetBird pin must be a 0.80.x release")
	}
	return nil
}

